mapper.update:

/* updateEsFiReg */
  UPDATE DONGOPKG A  
      SET A.RECV_FLAG = #{db_recv_flag},     
          A.STATUS = 'R',        
          A.ES_FI_WORK_DATE = SYSDATE,  
          A.ES_FI_STATUS = #{st_es_fi_status},    
          A.ES_FI_REMARK = #{st_es_fi_remark},      
          A.CHANGE_USER_ID = #{st_user_id},  
          A.CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
          A.CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS') 

    WHERE A.PLANT = #{st_plant}         
      AND A.BYCA_COMORG_CODE = #{st_byca_comorg_code}  
      AND A.BUYER = #{st_buyer}       
      AND A.OPKG_SEQ = #{st_opkg_seq}      
      AND A.RD_DATE = #{st_rd_date}      
      AND A.BUYER_ITEM_NO = #{st_buyer_item_no} 
      AND A.STATUS <> 'D'


/* updateMMReg */
  UPDATE DONGOPKG A  
      SET A.RECV_FLAG = #{db_recv_flag},      
          A.STATUS = 'R',        
          A.MM_WORK_DATE = SYSDATE,  
          A.MM_STATUS = #{db_mm_status},       
          A.DD_STATUS = DECODE(#{db_mm_status},'ED','RC',A.DD_STATUS), 
          A.MM_REMARK = #{st_mm_remark},     
          A.CHANGE_USER_ID = #{st_user_id}, 
          A.CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
          A.CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'), 
          A.IMAGE_KEY = #{st_image_key} 

    WHERE A.PLANT = #{st_plant}       
      AND A.BYCA_COMORG_CODE = #{st_byca_comorg_code} 
      AND A.BUYER = #{st_buyer}       
      AND A.OPKG_SEQ = #{st_opkg_seq}    
      AND A.RD_DATE = #{st_rd_date}      
      AND A.BUYER_ITEM_NO = #{st_buyer_item_no} 
      AND A.STATUS <> 'D'


